class Solution {
    public int visibleMountains(int[][] peaks) {
        int n = peaks.length;
        int[][] iv = new int[n][2];
        for (int i = 0; i < n; i++) iv[i] = new int[]{peaks[i][0] - peaks[i][1], peaks[i][0] + peaks[i][1]};
        Arrays.sort(iv, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(b[1], a[1]));
        int cnt = 0;
        long maxEnd = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            if (iv[i][1] > maxEnd) {
                maxEnd = iv[i][1];
                boolean dup = i + 1 < n && iv[i + 1][0] == iv[i][0] && iv[i + 1][1] == iv[i][1];
                if (!dup) cnt++;
            }
        }
        return cnt;
    }
}
